using System.Net;using System.Net.Http.Headers;using System.Net.Http.Json;using System.Text.Json;using AiCare.Domain;using AiCare.Infrastructure;using Microsoft.EntityFrameworkCore;using Microsoft.Extensions.DependencyInjection;using Xunit;
namespace AiCare.Tests;[Collection("Postgres regression")]public sealed class WorkforceGovernanceRegressionTests(PostgresRegressionFactory factory):IClassFixture<PostgresRegressionFactory>{[Fact]public async Task RestrictionsMedicationPoliciesEmployeeRecordsAndSelfServiceAreGoverned(){await factory.EnsureClinicalSeedAsync();var worker=Guid.NewGuid();var other=Guid.NewGuid();var person=Guid.NewGuid();var managerName=$"governance.manager.{Guid.NewGuid():N}";var coordinatorName=$"governance.coordinator.{Guid.NewGuid():N}";var workerName=$"governance.worker.{Guid.NewGuid():N}";var otherName=$"governance.other.{Guid.NewGuid():N}";using(var scope=factory.Services.CreateScope()){var db=scope.ServiceProvider.GetRequiredService<CareDbContext>();db.CareWorkers.AddRange(new CareWorker(worker,"Governed Worker","Medication administration","Flexible",0,0,"Valid","Compliant","Local",TenantDefaults.OrganizationId,TenantDefaults.BranchId),new CareWorker(other,"Other Worker","Care","Flexible",0,0,"Valid","Compliant","Local",TenantDefaults.OrganizationId,TenantDefaults.BranchId));db.ServiceUsers.Add(new ServiceUser(person,"Governance Person",new DateOnly(1980,1,1),"+100","Care","Contact","",RiskLevel.Low,"Onboarded","Address","None","None","Private","Regression","","Independent","Independent","Verbal","None","Standard",TenantDefaults.OrganizationId,TenantDefaults.BranchId));db.AppUsers.AddRange(User(managerName,UserRole.CareManager),User(coordinatorName,UserRole.CareCoordinator),User(workerName,UserRole.CareWorker,worker),User(otherName,UserRole.CareWorker,other));await db.SaveChangesAsync();await db.Database.ExecuteSqlInterpolatedAsync($"""insert into worker_competency_records(id,care_worker_id,organization_id,branch_id,competency,level,status,assessed_by,assessed_at,expires_at,notes) values({Guid.NewGuid()},{worker},{TenantDefaults.OrganizationId},{TenantDefaults.BranchId},'Medication administration','Competent','Valid','Manager',{DateTimeOffset.UtcNow.AddDays(-1)},{DateTimeOffset.UtcNow.AddYears(1)},'Regression')""");}
async Task<HttpClient> Login(string name){var c=factory.CreateClient();var r=await c.PostAsJsonAsync("/api/auth/login",new{userName=name,password="Admin123!",mfaCode=(string?)null});r.EnsureSuccessStatusCode();c.DefaultRequestHeaders.Authorization=new AuthenticationHeaderValue("Bearer",(await r.Content.ReadFromJsonAsync<Login>())!.Token);return c;}var manager=await Login(managerName);var coordinator=await Login(coordinatorName);var self=await Login(workerName);var outsider=await Login(otherName);var root=$"/api/phase1/workforce-governance/care-workers/{worker}";Assert.Equal(HttpStatusCode.OK,(await self.GetAsync(root)).StatusCode);Assert.Equal(HttpStatusCode.NotFound,(await outsider.GetAsync(root)).StatusCode);
var restrictionBody=new{restrictionType="Medication",skill="Medication administration",reason="Observed unsafe technique",evidenceReference="OBS-1",startsAt=DateTimeOffset.UtcNow.AddMinutes(-1),endsAt=(DateTimeOffset?)null};Assert.Equal(HttpStatusCode.Forbidden,(await coordinator.PostAsJsonAsync($"{root}/restrictions",restrictionBody)).StatusCode);Assert.Equal(HttpStatusCode.Created,(await manager.PostAsJsonAsync($"{root}/restrictions",restrictionBody)).StatusCode);var conflicts=await manager.PostAsJsonAsync("/api/phase1/visits/conflicts",new{serviceUserId=person,careWorkerId=worker,additionalCareWorkerIds=Array.Empty<Guid>(),startsAt=DateTimeOffset.UtcNow.AddDays(2),visitType="Medication",durationMinutes=30,requiredSkills="Medication administration"});Assert.Contains("medication-restricted",await conflicts.Content.ReadAsStringAsync());
Assert.Equal(HttpStatusCode.Created,(await manager.PostAsJsonAsync($"{root}/medication-authorization",new{status="Authorized",scope="Medication administration",evidenceReference="COMP-1",expiresAt=DateTimeOffset.UtcNow.AddMonths(6),reason=""})).StatusCode);Assert.Equal(HttpStatusCode.BadRequest,(await manager.PostAsJsonAsync($"{root}/medication-authorization",new{status="Suspended",scope="Medication administration",evidenceReference="COMP-2",expiresAt=(DateTimeOffset?)null,reason=""})).StatusCode);Assert.Equal(HttpStatusCode.Created,(await manager.PostAsJsonAsync($"{root}/medication-authorization",new{status="Suspended",scope="Medication administration",evidenceReference="COMP-2",expiresAt=(DateTimeOffset?)null,reason="Restriction review"})).StatusCode);
var policyResponse=await manager.PostAsJsonAsync("/api/phase1/workforce-governance/policies",new{title=$"Medication policy {Guid.NewGuid():N}",version="1.0",contentReference="POL-1",requiresAcknowledgement=true,organizationWide=true});Assert.Equal(HttpStatusCode.Created,policyResponse.StatusCode);var policy=JsonDocument.Parse(await policyResponse.Content.ReadAsStringAsync()).RootElement.GetProperty("id").GetGuid();Assert.Equal(HttpStatusCode.BadRequest,(await self.PostAsJsonAsync($"{root}/policies/{policy}/acknowledge",new{evidenceReference=""})).StatusCode);Assert.Equal(HttpStatusCode.Created,(await self.PostAsJsonAsync($"{root}/policies/{policy}/acknowledge",new{evidenceReference="Authenticated web acknowledgement"})).StatusCode);Assert.Equal(HttpStatusCode.Conflict,(await self.PostAsJsonAsync($"{root}/policies/{policy}/acknowledge",new{evidenceReference="Again"})).StatusCode);
Assert.Equal(HttpStatusCode.Forbidden,(await coordinator.PostAsJsonAsync($"{root}/employee-relations",new{caseType="Grievance",summary="Concern",owner="Manager",evidenceReference="ER-1"})).StatusCode);Assert.Equal(HttpStatusCode.Created,(await manager.PostAsJsonAsync($"{root}/employee-relations",new{caseType="Grievance",summary="Concern",owner="Manager",evidenceReference="ER-1"})).StatusCode);Assert.Equal(HttpStatusCode.Created,(await coordinator.PostAsJsonAsync($"{root}/wellbeing",new{category="Stress",summary="Support requested",action="Weekly check-in",owner="Manager",reviewDue=DateOnly.FromDateTime(DateTime.UtcNow.AddDays(7)),evidenceReference="WB-1"})).StatusCode);
var submitted=await self.PostAsJsonAsync($"{root}/requests",new{requestType="Leave",startsAt=DateTimeOffset.UtcNow.AddDays(5),endsAt=DateTimeOffset.UtcNow.AddDays(6),detail="Annual leave"});Assert.Equal(HttpStatusCode.Created,submitted.StatusCode);var request=JsonDocument.Parse(await submitted.Content.ReadAsStringAsync()).RootElement.GetProperty("id").GetGuid();Assert.Equal(HttpStatusCode.Forbidden,(await coordinator.PostAsJsonAsync($"{root}/requests/{request}/decide",new{decision="Approved",reason="Cover arranged"})).StatusCode);Assert.Equal(HttpStatusCode.OK,(await manager.PostAsJsonAsync($"{root}/requests/{request}/decide",new{decision="Approved",reason="Cover arranged"})).StatusCode);Assert.Equal(HttpStatusCode.Conflict,(await manager.PostAsJsonAsync($"{root}/requests/{request}/decide",new{decision="Rejected",reason="Again"})).StatusCode);var selfPayload=JsonDocument.Parse(await(await self.GetAsync(root)).Content.ReadAsStringAsync()).RootElement;Assert.Empty(selfPayload.GetProperty("employeeRelations").EnumerateArray());Assert.Contains(selfPayload.GetProperty("requests").EnumerateArray(),x=>x.GetProperty("status").GetString()=="Approved");using var verify=factory.Services.CreateScope();var verifyDb=verify.ServiceProvider.GetRequiredService<CareDbContext>();Assert.True(await verifyDb.AuditEvents.AnyAsync(x=>x.Action=="workforce.self_service_decided"));}
private static AppUser User(string n,UserRole r,Guid? w=null)=>new(Guid.NewGuid(),n,$"{n}@aicare.local",PasswordHasher.HashPassword("Admin123!"),r,true,TenantDefaults.OrganizationId,TenantDefaults.BranchId,w,null);private sealed record Login(string Token);}
